from pathlib import Path
import re
root = Path.cwd()
category = root / "categorie-resin.html"
image = root / "eigen-resin-ontwerp.webp"
if not category.is_file() or not image.is_file():
    raise SystemExit("Upload eerst eigen-resin-ontwerp.webp en dit script in de hoofdmap van de website.")
page = "<!doctype html><html lang=\"nl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Jouw eigen resin ontwerp | Makers 3D Labs</title><link rel=\"stylesheet\" href=\"assets/shop.css\"><link rel=\"stylesheet\" href=\"assets/bovenmenu.css?v=2\"><style>\nbody{margin:0;background:#242b38;color:#f5f6fa;font:16px/1.65 Arial,sans-serif}main{max-width:1240px;margin:auto;padding:32px 24px 56px}a{color:#99d5dc}h1{font-size:clamp(28px,4vw,44px);line-height:1.15;margin:14px 0}h2{font-size:22px}p{color:#cbd3df}.resin-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:24px;align-items:start}.resin-photo{width:100%;height:auto;display:block;border-radius:18px;background:#080b0d}.form-card{background:#2d3748;border:1px solid #526075;border-radius:18px;padding:24px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field.full{grid-column:1/-1}label{display:block;font-weight:700;font-size:14px;margin-bottom:5px}input,select,textarea{box-sizing:border-box;width:100%;background:#242b38;border:1px solid #65758a;border-radius:8px;padding:10px;color:#f5f6fa;font:inherit}textarea{min-height:110px;resize:vertical}.hint,.upload-error{font-size:13px;margin-top:5px}.upload-error{color:#ffc2c2}.upload-zone{padding:12px;border:1px dashed #83bbc5;border-radius:10px}.upload-list img{width:64px;height:64px;object-fit:cover;margin:6px}.check{display:flex;gap:10px;margin:18px 0}.check input{width:18px;flex-shrink:0}.check label{font-weight:400;font-size:13px}.action{background:#83cbd4;color:#142932;border:0;border-radius:10px;padding:13px 20px;font-weight:700;font-size:15px;cursor:pointer}.price{font-size:23px;color:#99d5dc;font-weight:700}@media(max-width:800px){.resin-grid{grid-template-columns:1fr}.resin-photo{max-height:460px;object-fit:contain}.fields{grid-template-columns:1fr}.field.full{grid-column:auto}}\n</style></head><body><header><a href=\"index.html\">Makers 3D Labs · Home</a></header><main><a href=\"categorie-resin.html\">← Terug naar resin</a><div class=\"resin-grid\"><div><img class=\"resin-photo\" src=\"eigen-resin-ontwerp.webp\" alt=\"Voorbeeld: een eigen drakenontwerp als schets en uitgewerkt resinbeeld\" width=\"1122\" height=\"1402\"><p>Digitaal ontwerpvoorbeeld ter inspiratie.</p></div><div><h1>Laat jouw eigen resin ontwerp maken.</h1><p>Een eigen personage, beeldje of bijzonder idee? Beschrijf jouw wensen en voeg een foto of schets toe. Vertel ook welk formaat, welke kleuren en afwerking je wilt.</p><p class=\"price\">Prijs op aanvraag</p><p>De prijs is nog niet bekend. We bekijken eerst of jouw ontwerp mogelijk is en sturen daarna een voorstel met een prijs. Je aanvraag is nog geen bestelling en je betaalt hier niets.</p><div class=\"form-card\"><h2>Stuur jouw idee door</h2><form id=\"quoteForm\" method=\"POST\" action=\"https://formsubmit.co/alejandrojenniferbruna@gmail.com\" enctype=\"multipart/form-data\"><input type=\"hidden\" name=\"_subject\" value=\"Eigen resin ontwerp | Makers 3D Labs\"><input type=\"hidden\" name=\"_captcha\" value=\"true\"><input type=\"text\" name=\"_honey\" tabindex=\"-1\" autocomplete=\"off\" style=\"position:absolute;left:-9999px\" aria-hidden=\"true\"><div class=\"fields\"><div class=\"field\"><label for=\"naam\">Naam <span>*</span></label><input id=\"naam\" name=\"naam\" type=\"text\" autocomplete=\"name\" maxlength=\"120\" required placeholder=\"Jouw naam\"></div><div class=\"field\"><label for=\"bedrijf\">Bedrijfsnaam</label><input id=\"bedrijf\" name=\"bedrijf\" type=\"text\" autocomplete=\"organization\" maxlength=\"120\" placeholder=\"Optioneel\"></div><div class=\"field\"><label for=\"email\">E-mailadres <span>*</span></label><input id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"180\" required placeholder=\"naam@voorbeeld.nl\"></div><div class=\"field\"><label for=\"telefoon\">Telefoonnummer</label><input id=\"telefoon\" name=\"telefoon\" type=\"tel\" autocomplete=\"tel\" maxlength=\"40\" placeholder=\"Optioneel\"></div><div class=\"field\"><label for=\"product\">Welk product of welke dienst? <span>*</span></label><input id=\"product\" name=\"product\" value=\"Eigen resin ontwerp\" readonly></div><div class=\"field\"><label for=\"aantal\">Aantal</label><input id=\"aantal\" name=\"aantal\" type=\"number\" min=\"1\" max=\"100000\" step=\"1\" placeholder=\"Bijv. 50\"><div class=\"hint\">Mag leeg blijven als je dit nog niet weet.</div></div><div class=\"field full\"><label for=\"datum\">Gewenste leverdatum</label><input id=\"datum\" name=\"datum\" type=\"date\"><div class=\"hint\">Een gewenste datum is geen gegarandeerde levertijd.</div></div><div class=\"field full\"><label for=\"omschrijving\">Beschrijf jouw idee <span>*</span></label><textarea id=\"omschrijving\" name=\"omschrijving\" maxlength=\"3000\" minlength=\"10\" required placeholder=\"Wat wil je laten maken? Denk aan formaat, kleuren, toepassing en andere wensen.\"></textarea></div><div class=\"field full\"><label for=\"fotos\">Foto’s of voorbeeldafbeeldingen toevoegen (optioneel)</label><div class=\"upload-zone\"><input type=\"file\" id=\"fotos\" name=\"fotos\" accept=\"image/jpeg,image/png,image/webp\" multiple aria-describedby=\"fotoHint fotoError\"><div class=\"hint\" id=\"fotoHint\">Maximaal 5 afbeeldingen · JPG, PNG of WebP · Samen maximaal 9 MB.</div><div class=\"upload-list\" id=\"uploadList\" aria-live=\"polite\"></div><div class=\"upload-error\" id=\"fotoError\" role=\"alert\"></div></div></div></div><div class=\"check\"><input type=\"checkbox\" id=\"akkoord\" required><label for=\"akkoord\">Ik geef toestemming om mijn ingevulde gegevens en eventuele afbeeldingen via FormSubmit naar Makers 3D Labs te versturen voor het behandelen van mijn aanvraag. <span>*</span></label></div><button class=\"action\" type=\"submit\">Offerteaanvraag versturen →</button></form><p class=\"hint\">Na activering van de formulierdienst wordt je aanvraag per e-mail doorgestuurd. <a href=\"informatie.html\">Informatie &amp; voorwaarden</a></p></div></div></div></main><script>\n(()=>{const input=document.getElementById('fotos'),form=document.getElementById('quoteForm'),error=document.getElementById('fotoError'),list=document.getElementById('uploadList');let urls=[];function check(){urls.forEach(URL.revokeObjectURL);urls=[];list.replaceChildren();const files=Array.from(input.files);let message='';if(files.length>5)message='Kies maximaal 5 afbeeldingen.';else if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)))message='Gebruik JPG, PNG of WebP.';else if(files.reduce((n,f)=>n+f.size,0)>9*1024*1024)message='De afbeeldingen mogen samen maximaal 9 MB zijn.';error.textContent=message;input.setCustomValidity(message);if(!message)files.forEach(f=>{const img=document.createElement('img');img.src=URL.createObjectURL(f);urls.push(img.src);img.alt=f.name;list.append(img)});return !message}input.addEventListener('change',check);form.addEventListener('submit',e=>{if(!check()){e.preventDefault();input.reportValidity()}})})();\n</script><script src=\"assets/shop-data.js\"></script><script src=\"assets/shop.js\"></script><script src=\"assets/bovenmenu.js?v=2\"></script></body></html>"
card = "<article id=\"eigen-resin-product\" class=\"category-product\" data-name=\"Eigen resin ontwerp op maat\" data-colors=\"[&quot;Meerkleurig&quot;,&quot;Op aanvraag&quot;]\" data-kind=\"Beelden\" data-price=\"\" data-personal=\"true\"><a class=\"category-product-photo\" href=\"eigen-resin.html\"><img src=\"eigen-resin-ontwerp.webp\" alt=\"Jouw schets uitgewerkt als resinbeeld — digitaal ontwerpvoorbeeld\" loading=\"lazy\" width=\"1122\" height=\"1402\"></a><div class=\"category-product-body\"><span class=\"category-product-type\">Jouw eigen ontwerp</span><h2>Laat jouw eigen resin ontwerp maken</h2><p>Stuur jouw idee, foto of schets. Wij bekijken de mogelijkheden en sturen je een prijsvoorstel.</p><strong class=\"category-price\">Prijs op aanvraag</strong><a class=\"category-product-link\" href=\"eigen-resin.html\">Stuur jouw idee en afbeeldingen →</a></div></article>"
html = category.read_text(encoding="utf-8")
html = re.sub(r'<article\b[^>]*id="eigen-resin-product"[^>]*>[\s\S]*?</article>', '', html)
html, count = re.subn(r'(<div\b[^>]*id="category-products"[^>]*>)', lambda m: m.group(1)+card, html, count=1)
if count != 1:
    raise SystemExit("Productoverzicht niet gevonden; geen bestanden aangepast.")
(root / "eigen-resin.html").write_text(page, encoding="utf-8")
category.write_text(html, encoding="utf-8")
print("Klaar: eigen resin ontwerp toegevoegd. Prijs op aanvraag, idee en foto-upload. Nog niet gepubliceerd.")
